"""Worked RAP comparisons for the questions that previously lacked a clear picture."""
from visual_modern import base,panel,table,note,make,txt,rect,arrow,lines,INK,TEAL,AMBER,PALE,white

def build_rap_recall_visuals():
 out=[]
 d=base('Choose who owns interaction and persistence','Compare implementation responsibilities, not the age of the application')
 table(d,32,406,816,['Scenario','Interaction buffer','Persistence'],[
 ['Managed','Framework','Framework'],['Managed + unmanaged save','Framework','Application saver'],['Unmanaged','Application','Application saver']], [1.6,1,1],52)
 panel(d,36,124,390,108,'Existing API fits?','Check transaction ownership, supported save phase, numbering and failure behavior.')
 panel(d,452,124,390,108,'Commit owner stays fixed','A behavior implementation cannot take over transaction completion with COMMIT WORK.')
 note(d,'Additional save supplements managed persistence. It is not the same as replacing persistence with unmanaged save.')
 out.append(make('rap-save-ownership-matrix','RAP implementation ownership matrix','RAP-02 SRAP-01 SRAP-02','Trace the same request through three implementation choices and name the owner of each responsibility.','Which part stays managed when only the save implementation is replaced?','Conceptual comparison; specific saver variants and failure support depend on release and scenario.',d))
 d=base('Early and late numbering: know which identity you hold','Example: a new order has request identity before its final document number')
 table(d,35,403,810,['Moment','Early numbering example','Late numbering example'],[
 ['Create request','%cid = NEW_1','%cid = NEW_1'],['Interaction','Final key already assigned','Preliminary identity as configured'],['ADJUST_NUMBERS','No late assignment needed','Map preliminary to final key'],['After successful save','Consumer has saved key','Consumer resolves final key']], [1,1.5,1.7],48)
 lines(d,45,157,'A generated UUID and a gap-sensitive business document number solve different requirements. Do not return a preliminary identifier as a saved final document number.',102,15)
 note(d,'Final key allocation is not proof of commit. Rollback can still affect the outcome; numbering and persistence contracts must be checked.')
 out.append(make('rap-numbering-timeline','RAP identity and numbering timeline','RAP-10 RAP-11 SRAP-07 SRAP-08','Compare when the identity becomes final and when persistence is confirmed.','What must an external EML consumer inspect after MODIFY and after COMMIT?','Illustrative numbering paths; exact %pid/%pre mapping and conversion syntax are release/scenario-specific.',d))
 d=base('Augmentation adapts the request; additional save adds work','Two hooks at different boundaries, not interchangeable extension techniques')
 panel(d,35,294,380,143,'Projection request','Convenience input arrives. Augmentation enriches supported underlying modifications.')
 panel(d,463,294,380,143,'Managed persistence','The framework saves owned data. Additional save performs supported supplementary work.')
 arrow(d,421,364,456,364)
 table(d,35,174,808,['Question','Augmentation','Additional save'],[['Where?','Projection interaction','Save sequence'],['Example','Derive underlying request input','Write supported audit data']], [1,1.65,1.65],40)
 note(d,'Neither hook authorizes an independent COMMIT. Choose by contract, not by an assumption that any hook can change any data.')
 out.append(make('rap-augmentation-additional-save','Augmentation versus additional save','ADV-06 SRAP-02 SRAP-14','Locate the input transformation and persistence supplement on the same conceptual timeline.','Why would writing an audit row not make augmentation the right save hook?','The arrow is conceptual; availability, supported fields and trigger details depend on the target RAP release.',d))
 d=base('Entity ETag and total ETag protect different checks','One order root, one child change, two concurrency situations')
 panel(d,34,290,391,153,'Entity conditional update','Alice and Ben read the same entity version. Alice saves. Ben submits the old If-Match value.')
 panel(d,456,290,391,153,'Draft resume after lock expiry','A draft was based on active state. Another process changes an active child. Resume must detect a stale base.')
 table(d,35,180,810,['Check','Protects','Expected response'],[['Entity ETag','Same entity update version','Reject stale conditional update'],['Total ETag','Relevant active BO state','Detect stale draft on resume']], [1,1.3,1.9],43)
 note(d,'Use two independent contexts for a real concurrency test. A child-only change must participate in the required total-ETag contract.')
 out.append(make('rap-two-etag-boundaries','Two ETag boundaries','ADV-01 SRAP-10 OPS-05','The left side tests a conditional entity update; the right tests the active-state basis of a resumed draft.','Why does testing one entity ETag not prove the draft total-ETag implementation?','ETags are opaque. Verify lock expiry, relevant child changes and generated behavior on the actual system.',d))
 d=base('The backend is right, but the screen is stale','Separate business-state correctness from the consumer refresh contract')
 panel(d,34,300,230,134,'1  Quantity changes','Input: quantity 2 -> 3. Backend determines total 300.')
 panel(d,323,300,232,134,'2  Response / metadata','Action result and supported side effects identify what needs refreshing.')
 panel(d,614,300,232,134,'3  Consumer refresh','Inspect actual requests. The UI must retrieve and display the new total.')
 arrow(d,269,366,317,366);arrow(d,560,366,607,366)
 table(d,40,174,798,['Observation','Next investigation'],[['Backend still says 200','Calculation / transactional read'],['Backend says 300; UI says 200','Side-effect targets / response / binding']], [1.4,2.2],43)
 note(d,'A page reload can hide the symptom. It does not explain the missing refresh contract, and another commit is not a refresh mechanism.')
 out.append(make('rap-side-effect-diagnosis','Side effects and stale UI diagnosis','ADV-07 SRAP-21 OPS-06','Use the observed backend value to choose the next debugging branch.','What request proves that the consumer refreshed the calculated total?','Consumer and metadata support are release-dependent; a valid backend side effect is not proof that every client processes it.',d))
 d=base('State messages need an invalidation story','Example: an invalid child date is corrected in a later draft request')
 table(d,34,405,814,['Moment','Business state','Message decision'],[['Request 1','Child date inconsistent','Report state error for that child'],['Request 2','User corrects the date','Invalidate relevant prior state message'],['Revalidation','State is now consistent','Do not recreate the old error'],['Transition failure','Operation itself failed','Return transition-related feedback']], [1.1,1.4,1.7],47)
 lines(d,45,146,'Trace instance identity, state area and element/path targeting. A correct text attached to the wrong child is still incorrect behavior.',100,15)
 note(d,'REPORTED carries messages; the supported FAILED response rejects instances. Message severity alone is not a general rejection mechanism.')
 out.append(make('rap-message-lifecycle','RAP message lifecycle and correction','ADV-08 SRAP-24 RAP-07','Follow the same child through an error and correction instead of treating a message as timeless text.','Which identity and state area would you inspect when the old error remains?','Message lifetime and permitted state-message scenarios depend on active/draft and the supported operation contract.',d))
 d=base('Optimize at the layer that owns the requirement','A remote virtual field changes the query cost and supported operations')
 table(d,35,402,810,['Requirement','Possible design','Verification'],[['Display enrichment','Batch remote lookup','Calls and missing-data policy'],['Filter before paging','Push predicate / persisted value','Complete result semantics'],['Sort million-row list','Supported sortable data model','Stable global order'],['Analytical aggregate','Correct grain / pushdown','Units, currency and row count']], [1.2,1.65,1.4],47)
 panel(d,38,110,806,94,'Bad shortcut: enrich one page, then sort it','Sorting ten fetched rows does not produce the correct top ten across a million candidates. A display calculation does not automatically support database filtering or sorting.')
 note(d,'Choose supported provider and consumer capabilities on the target release; do not assume every virtual element can push filters or ordering down.')
 out.append(make('rap-query-calculation-placement','Calculation placement and query semantics','CDS-09 MODEL-07 MODEL-08 MODEL-09 MODEL-18 OPS-08','Use the requirement to decide where a value must exist before filtering, ordering or aggregation.','Why can a correct calculation still yield a wrong page of results?','Architecture alternatives, not a promise that all listed options are supported by each projection/custom provider.',d))
 d=base('A green language check is one gate, not the whole release','Move from source eligibility to the consumer and operational contract')
 for x,title,body in [(34,'Language / API','Allowed syntax, released dependencies and visibility.'),(314,'BO contract','Strict behavior rules, security, transaction and compatibility.'),(594,'Delivery evidence','Target activation, service access, tests and recovery.')]:panel(d,x,266,252,170,title,body)
 arrow(d,291,349,308,349);arrow(d,571,349,588,349)
 lines(d,48,198,'A released BO interface can expose a narrower supported contract than the underlying implementation. Consume the permitted layer, even when ADT can display more objects.',98,15)
 note(d,'strict(2), C1 release and a working service binding are different facts. None alone certifies production readiness.')
 out.append(make('rap-release-gates','RAP release and consumption gates','SRAP-16 SRAP-22 CLOUD-06 CLOUD-10 CLOUD-13 CLOUD-17 OPS-09 OPS-10 OPS-14','Review eligibility, behavior and delivery as separate evidence gates.','Which gate would catch an API-compatible change that breaks deployment configuration?','A teaching checklist; exact release contracts, component visibility and delivery tools depend on the product.',d))
 return out
